import json,subprocess,datetime
d=json.load(open('/tmp/r.json'))
u=lambda m:datetime.datetime.fromtimestamp(m/1000,datetime.timezone.utc).strftime('%m-%d %H:%M')
c=[]
for k,a in d['accounts'].items():
  for t in a.get('trades',[]):
    if t.get('run') is not None and not t['open']: c.append((k,t))
c.sort(key=lambda z:z[1]['t_in'])
for k,t in c[:3]+c[-3:]:
  o=subprocess.run(['curl','-s','localhost:8091/api/prop_chart?run=%d&t_in=%d&side=%s'%(t['run'],t.get('kt',t['t_in']),t['side'])],capture_output=True,text=True).stdout
  try:
    D=json.loads(o);ch=D['chart'];print(k,t['sym'],t['tf'],u(t['t_in']),'n',len(ch['t']),u(ch['t'][0]),u(ch['t'][-1]),'out',u(D['t_out']))
  except Exception as e: print(k,t['sym'],u(t['t_in']),o[:120])
